users = []

def add_user():
    name = input("Имя: ")
    age = int(input("Возраст: "))
    users.append({"name": name, "age": age})

def show_users():
    if len(users) == 0:
        print("Пусто")
    for user in users:
        print(user["name"], user["age"])

def find_user():
    name = input("Имя для поиска: ").lower()
    for user in users:
        if user["name"].lower() == name:
            print(user["name"], user["age"])
            return
    print("Не найден")

def save_users():
    with open("users.txt", "w", encoding="utf-8") as f:
        for user in users:
            f.write(user["name"] + " " + str(user["age"]) + "\n")
    print("Сохранено в users.txt")

