import math

def Power1(a, b):
    if a <= 0:
        return 0
    return math.exp(b * math.log(a))

def Power2(a, n):
    p = 1
    for i in range(abs(n)):
        p *= a
    if n < 0:
        return 1 / p
    return p

def Power3(a, b):
    if b == int(b):
        return Power2(a, round(b))
    return Power1(a, b)

