import os
import struct

def read_ints(name):
    with open(name, "rb") as f:
        data = f.read()
    return list(struct.unpack(str(len(data) // 4) + "i", data))

def write_ints(name, lst):
    with open(name, "wb") as f:
        f.write(struct.pack(str(len(lst)) + "i", *lst))

def read_reals(name):
    with open(name, "rb") as f:
        data = f.read()
    return list(struct.unpack(str(len(data) // 8) + "d", data))

def write_reals(name, lst):
    with open(name, "wb") as f:
        f.write(struct.pack(str(len(lst)) + "d", *lst))

def read_text(name):
    with open(name, encoding="utf-8") as f:
        return f.read()

def write_text(name, s):
    with open(name, "w", encoding="utf-8") as f:
        f.write(s)

def read_lines(name):
    return read_text(name).splitlines()

def write_lines(name, lst):
    write_text(name, "\n".join(lst))

def read_bytes(name):
    with open(name, "rb") as f:
        return f.read()

def write_bytes(name, data):
    with open(name, "wb") as f:
        f.write(data)

